/* Popover, dropdown menu and select content on Radix: a bordered panel above the page. */
.popover { z-index: var(--z-drawer); min-width: 200px; max-width: min(360px, 92vw); padding: var(--s4); background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); animation: dialog-fade var(--fast) var(--ease); }
.popover:focus-visible { outline-offset: 2px; }
.menu-content { z-index: var(--z-drawer); min-width: 200px; padding: var(--s1) 0; background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); animation: dialog-fade var(--fast) var(--ease); }
.menu-content .menu-item { cursor: pointer; }
.menu-content .menu-item[data-highlighted] { background: var(--foreground); color: var(--background); outline: none; }
.menu-content .menu-item[data-disabled] { opacity: 0.5; pointer-events: none; }
.menu-content .menu-item[data-variant="danger"][data-highlighted] { background: var(--danger); }
.menu-label { padding: var(--s2) var(--s4); font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.menu-indicator { width: 14px; display: inline-flex; justify-content: center; }
.menu-item-check { display: flex; align-items: center; gap: var(--s3); }

/* ─── Dropdown menu: <details class="dropdown">; monoline.js closes it on Escape and outside click ─── */
.dropdown { position: relative; display: inline-block; }
.dropdown > summary { list-style: none; cursor: pointer; }
.dropdown > summary::-webkit-details-marker { display: none; }
.menu { position: absolute; inset-inline-start: 0; top: calc(100% + var(--s2)); z-index: var(--z-drawer); min-width: 200px; background: var(--background); border: 1px solid var(--foreground); padding: var(--s1) 0; }
.menu-end { inset-inline-start: auto; inset-inline-end: 0; }
.menu-item { overflow-wrap: anywhere; display: flex; justify-content: space-between; gap: var(--s5); width: 100%; padding: var(--s2) var(--s4); font-size: var(--text-sm); text-align: start; }
.menu-item:hover, .menu-item:focus-visible { background: var(--foreground); color: var(--background); outline-offset: -2px; }
.menu-item.danger:hover { background: var(--danger); color: var(--background); }
.menu-sep { border: 0; border-top: 1px solid var(--rule); margin: var(--s1) 0; }

/* Menubar: a thin bar of text triggers. The panels reuse .menu-content from popover.css. */
.menubar { display: inline-flex; border: 1px solid var(--foreground); }
.menubar-trigger { padding: var(--s2) var(--s4); font-size: var(--text-sm); }
.menubar-trigger + .menubar-trigger { border-inline-start: 1px solid var(--rule); }
.menubar-trigger:hover, .menubar-trigger[data-state="open"], .menubar-trigger[data-highlighted] { background: var(--foreground); color: var(--background); outline: none; }
.menubar-trigger:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }

